class BinaryMinHeap:
    def __init__(self):
        self.heap = []

    def insert(self, value):
        self.heap.append(value)
        self._bubble_up(len(self.heap) - 1)

    def delete_min(self):
        if self.is_empty():
            raise IndexError("Heap is empty")

        if len(self.heap) == 1:
            return self.heap.pop()

        min_value = self.heap[0]
        self.heap[0] = self.heap.pop()
        self._sink_down(0)
        return min_value

    def search(self, value):
        if self.is_empty():
            raise IndexError("Heap is empty")

        for i in range(len(self.heap)):
            if self.heap[i] == value:
                return True
        return False

    def merge(self, other_heap):
        if not isinstance(other_heap, BinaryMinHeap):
            raise TypeError("Can only merge with another BinaryMinHeap")

        merged_heap = BinaryMinHeap()
        merged_heap.heap = self.heap + other_heap.heap
        merged_heap._build_heap()
        return merged_heap

    def print_sorted(self):
        sorted_elements = []
        heap_copy = self.heap.copy()
        while not self.is_empty():
            sorted_elements.append(self.delete_min())

        self.heap = heap_copy
        return sorted_elements

    def find_kth_smallest(self, k):
        if self.is_empty():
            raise IndexError("Heap is empty")

        if k < 1 or k > len(self.heap):
            raise IndexError("Invalid k value")

        k_smallest = None
        heap_copy = self.heap.copy()
        for _ in range(k):
            k_smallest = self.delete_min()

        self.heap = heap_copy
        return k_smallest

    def update_value(self, old_value, new_value):
        if self.is_empty():
            raise IndexError("Heap is empty")

        for i in range(len(self.heap)):
            if self.heap[i] == old_value:
                self.heap[i] = new_value
                if new_value < old_value:
                    self._bubble_up(i)
                else:
                    self._sink_down(i)
                return

        raise ValueError("Value not found in the heap")

    def is_empty(self):
        return len(self.heap) == 0

    def clear(self):
        self.heap = []

    def _bubble_up(self, index):
        parent_index = (index - 1) // 2
        while index > 0 and self.heap[index] < self.heap[parent_index]:
            self.heap[index], self.heap[parent_index] = self.heap[parent_index], self.heap[index]
            index = parent_index
            parent_index = (index - 1) // 2

    def _sink_down(self, index):
        left_child_index = 2 * index + 1
        right_child_index = 2 * index + 2
        smallest = index

        if left_child_index < len(self.heap) and self.heap[left_child_index] < self.heap[smallest]:
            smallest = left_child_index

        if right_child_index < len(self.heap) and self.heap[right_child_index] < self.heap[smallest]:
            smallest = right_child_index

        if smallest != index:
            self.heap[index], self.heap[smallest] = self.heap[smallest], self.heap[index]
            self._sink_down(smallest)

    def _build_heap(self):
        for i in range(len(self.heap) // 2, -1, -1):
            self._sink_down(i)
```

